def parse_nested_parens(paren_string: str) -> List[int]:
    def get_depth(s, depth):
        if len(s) == 0:
            return depth
        if s[0] == '(':
            return get_depth(s[1:], depth + 1)
        if s[0] == ')':
            return get_depth(s[1:], depth - 1)
        return get_depth(s[1:], depth)

    return [get_depth(parens, 0) for parens in paren_string.split()]

