def parse_nested_parens(paren_string: str) -> List[int]:
    def parse_group(group: str) -> int:
        level = 0
        max_level = 0
        for char in group:
            if char == '(':
                level += 1
                max_level = max(max_level, level)
            elif char == ')':
                level -= 1
        return max_level

    return [parse_group(group) for group in paren_string.split()]
