    for char in message:
        if char.isalpha():
            # Swap case
            if char.isupper():
                char = char.lower()
            else:
                char = char.upper()
            # Replace vowels with the letter 2 places ahead of that vowel
            if char in vowels:
                new_char = chr(ord(char) + 2)
                if new_char in vowels:
                    new_char = chr(ord(new_char) + 2)
            result += new_char
        else:
            result += char
    return result

