def is_nested(string):
    count = 0
    max_count = 0
    for char in string:
        if char == '[':
            count += 1
            if count > max_count:
                max_count = count
        elif char == ']':
            count -= 1
        # If count is ever negative, it means there is no way to nest brackets
        if count < 0:
            return False

    # A valid subsequence of brackets is one where at least one bracket is nested
    # So, we need to check if max_count is greater than 1
    return max_count > 1
```

