    expression = ''
    for i, op in enumerate(operator):
        if op == '+':
            expression += ' + ' + str(operand[i])
        elif op == '-':
            expression += ' - ' + str(operand[i])
        elif op == '*':
            expression += ' * ' + str(operand[i])
        elif op == '//':
            expression += ' // ' + str(operand[i])
